public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If any string is empty, no non-empty substring can be common
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }
    String first = strings.get(0);
    int maxLen = 0;
    int n = first.length();
    // Iterate lengths from longest to shortest
    for (int len = n; len > 0; len--) {
        // For each possible substring of this length in the first string
        for (int start = 0; start <= n - len; start++) {
            String candidate = first.substring(start, start + len);
            String reverse = new StringBuilder(candidate).reverse().toString();
            boolean allMatch = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(reverse))) {
                    allMatch = false;
                    break;
                }
            }
            if (allMatch) {
                return len;
            }
        }
    }
    return 0;
}

