public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        return 0;
    }
    java.util.Set<Integer> set = new java.util.HashSet<>();
    for (int n : numbers) {
        set.add(n);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 == 0 && set.contains(n / 2)) {
            count++;
        }
    }
    return count;
}

