public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int dim = start.length;
    String startKey;
    String endKey;
    if (dim == 1) {
        startKey = Integer.toString(start[0]);
        endKey = Integer.toString(end[0]);
    } else {
        startKey = java.util.Arrays.toString(start);
        endKey = java.util.Arrays.toString(end);
    }
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path.length == 2) {
            String a = Integer.toString(path[0]);
            String b = Integer.toString(path[1]);
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        } else if (path.length == 2 * dim) {
            int[] c1 = java.util.Arrays.copyOfRange(path, 0, dim);
            int[] c2 = java.util.Arrays.copyOfRange(path, dim, 2 * dim);
            String a = java.util.Arrays.toString(c1);
            String b = java.util.Arrays.toString(c2);
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        } else {
            // ignore invalid path
        }
    }
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

