public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid date";
    }
    date = date.trim();
    String[] parts = date.split("\\s+");
    if (parts.length != 3) {
        return "Invalid date";
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        return "Invalid date";
    }
    try {
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.Month monthEnum = java.time.Month.of(month);
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
        String monthName = monthEnum.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String weekdayName = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (java.time.DateTimeException e) {
        return "Invalid date";
    }
}

