public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length < 2) continue;
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            parent[nei] = node;
            stack.push(nei);
        }
    }
    int[] times = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        int time = 0;
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            if (times[nei] > 0 || hasApple[nei]) {
                time += times[nei] + 2;
            }
        }
        times[node] = time;
    }
    return times[0];
