public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    // dp[k] holds possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Long>[] dp = new HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) dp[i] = new HashSet<>();
    dp[0].add(0L);
    for (int num : nums) {
        // iterate k from maxK down to 1
        for (int k = Math.min(maxK, n - 1); k >= 1; k--) {
            for (Long prevSum : dp[k - 1]) {
                long newSum = prevSum + num;
                dp[k].add(newSum);
            }
        }
        // after adding this number, check for any valid subset
        for (int k = 1; k <= maxK; k++) {
            if (totalSum * k % n != 0) continue;
            long target = totalSum * k / n;
            if (dp[k].contains(target)) return true;
        }
    }
    return false;
}

