public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0;
    }
    int prev2 = 0; // cost to reach step i-2
    int prev1 = 0; // cost to reach step i-1
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

