public boolean hasAllCodes(String s, int k) {
    if (k > s.length() || k <= 0) {
        return false;
    }
    // If k is too large, the number of possible codes (1 << k) would overflow an int.
    // In such a case, it's impossible for the string to contain all codes.
    if (k >= 31) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen[code] = true;
        }
    }
    for (boolean present : seen) {
        if (!present) {
            return false;
        }
    }
    return true;
}

