public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // need an opening bracket before this ')'
                insertions++;
            } else {
                balance--; // match with an existing '('
            }
        } else {
            // invalid character, ignore or throw exception
            // For safety, we can skip or treat as error
        }
    }
    // any remaining unmatched '(' need a closing ')'
    insertions += balance;
    return insertions;
}

