public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[][] dp = new int[n + 1][1 << n];
    for (int i = 0; i <= n; i++) java.util.Arrays.fill(dp[i], -1);
    class Solver {
        int dfs(int prev, int mask) {
            if (mask == (1 << n) - 1) return 1;
            int keyPrev = prev == -1 ? n : prev;
            int memo = dp[keyPrev][mask];
            if (memo != -1) return memo;
            int count = 0;
            java.util.HashSet<Integer> used = new java.util.HashSet<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (used.contains(A[i])) continue;
                if (prev == -1 || isSquare(A[prev] + A[i])) {
                    used.add(A[i]);
                    count += dfs(i, mask | (1 << i));
                }
            }
            dp[keyPrev][mask] = count;
            return count;
        }
        boolean isSquare(int sum) {
            int r = (int) java.lang.Math.sqrt(sum);
            return r * r == sum;
        }
    }
    Solver solver = new Solver();
    return solver.dfs(-1, 0);
}

