public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int i = 0, j = 0;
    int dir = 0; // 0 = up-right, 1 = down-left
    for (int k = 0; k < m * n; k++) {
        result[k] = mat[i][j];
        if (dir == 0) { // moving up-right
            if (j == n - 1) { // hit right boundary
                i++;
                dir = 1;
            } else if (i == 0) { // hit top boundary
                j++;
                dir = 1;
            } else { // move diagonally up-right
                i--;
                j++;
            }
        } else { // moving down-left
            if (i == m - 1) { // hit bottom boundary
                j++;
                dir = 0;
            } else if (j == 0) { // hit left boundary
                i++;
                dir = 0;
            } else { // move diagonally down-left
                i++;
                j--;
            }
        }
    }
    return result;
}

